def _get_residuals(x, y, t, k, w):
    w2 = w ** 2
    _, _, c = _lsq_solve_qr(x, y, t, k, w)
    c = np.ascontiguousarray(c)
    spl = BSpline(t, c, k)
    residuals = _compute_residuals(w2, spl(x), y)
    fp = residuals.sum()
    if np.isnan(fp):
        raise ValueError(_iermesg[1])
    return (residuals, fp)

def _compute_residuals(w2, splx, y):
    delta = ((splx - y) ** 2).sum(axis=1)
    return w2 * delta

def _validate_inputs(x, y, w, k, s, xb, xe, parametric):
    """Common input validations for generate_knots and make_splrep.
    """
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if w is None:
        w = np.ones_like(x, dtype=float)
    else:
        w = np.asarray(w, dtype=float)
        if w.ndim != 1:
            raise ValueError(f'w.ndim = {w.ndim!r} not implemented yet.')
        if (w < 0).any():
            raise ValueError('Weights must be non-negative')
    if y.ndim == 0 or y.ndim > 2:
        raise ValueError(f'y.ndim = {y.ndim!r} not supported (must be 1 or 2.)')
    parametric = bool(parametric)
    if parametric:
        if y.ndim != 2:
            raise ValueError(f'y.ndim = {y.ndim!r} != 2 not supported with parametric ={parametric!r}.')
    else:
        if y.ndim != 1:
            raise ValueError(f'y.ndim = {y.ndim!r} != 1 not supported with parametric ={parametric!r}.')
        y = y[:, None]
    if w.shape[0] != x.shape[0]:
        raise ValueError(f'Weights is incompatible: w.shape ={w.shape!r} != {x.shape}.')
    if x.shape[0] != y.shape[0]:
        raise ValueError(f'Data is incompatible: x.shape = {x.shape!r} and y.shape = {y.shape!r}.')
    if x.ndim != 1 or (x[1:] < x[:-1]).any():
        raise ValueError('Expect `x` to be an ordered 1D sequence.')
    k = operator.index(k)
    if s < 0:
        raise ValueError(f'`s` must be non-negative. Got s = {s!r}')
    if xb is None:
        xb = min(x)
    if xe is None:
        xe = max(x)
    return (x, y, w, k, s, xb, xe)

def prodd(t, i, j, k):
    res = 1.0
    for s in range(k + 2):
        if i + s != j:
            res *= t[j] - t[i + s]
    return res
